def extract_list(mesh_str, key):
    pattern = rf"{key}\s*=\s*\[([^\]]*)\]"
    match = re.search(pattern, mesh_str, re.MULTILINE | re.DOTALL)
    if match:
        list_str = "[" + match.group(1) + "]"
        try:
            return ast.literal_eval(list_str)
        except Exception:
            return []
    return []


extent = np.array(extract_list(usd_mesh, "extent"))
normals = np.array(extract_list(usd_mesh, "normals"))
points = np.array(extract_list(usd_mesh, "points"))

extent *= 0.001
points *= 0.001


"""prop"""
centroid = np.mean(points, axis=0)
extent_centered = extent - centroid
normals = normals
points_centered = points - centroid

U, S, Vt = np.linalg.svd(points_centered, full_matrices=False)
v_min = Vt[-1, :]
if v_min[2] < 0:
    v_min = -v_min
e_z = np.array([0.0, 0.0, 1.0])

rotation = R.from_rotvec(R.align_vectors([e_z], [v_min])[0].as_rotvec())

extent_transformed = rotation.apply(extent_centered)
normals_transformed = rotation.apply(normals)
points_transformed = rotation.apply(points_centered)


