def format_list(name, data, float_type="float3"):
    if "extent" in name:
        float_type = "float3"
    elif "normal" in name:
        float_type = "normal3f"
    elif "point" in name:
        float_type = "point3f"
    formatted = f"{float_type}[] {name} = ["
    for tuple_ in data:
        formatted += f"({', '.join(f'{v:.6f}' for v in tuple_)}), "
    formatted = formatted.rstrip(", ") + "]"
    if "normal" in name:
        formatted += " (" 
    return formatted


